def transform(grid):
    """Restore 2-masked cells using the square grid's dihedral symmetries."""
    h, w = len(grid), len(grid[0])
    if h != w:
        raise ValueError("expected a square grid")
    out = [row[:] for row in grid]
    n = h
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                orbit = ((r, c), (r, n-1-c), (n-1-r, c), (n-1-r, n-1-c),
                         (c, r), (c, n-1-r), (n-1-c, r), (n-1-c, n-1-r))
                for rr, cc in orbit:
                    if grid[rr][cc] != 2:
                        out[r][c] = grid[rr][cc]
                        break
    return out
